import * as React from 'react';
/**
 * The props passed to a custom `bodyTemplate` component for `AgentStep`-based components
 * (`Reasoning`, `ChainOfThought`, `ToolCall`).
 *
 * When a `bodyTemplate` is provided, the component renders the custom component
 * instead of the default step body. The original `children` are passed through
 * so the template can choose how (or whether) to render them.
 *
 * @hidden
 */
export interface AgentStepBodyTemplateProps {
    /** The original step children (e.g. `Thought` rows, text content). */
    children?: React.ReactNode;
    /** Whether the step is currently expanded. */
    expanded?: boolean;
    /** Whether the step is completed. */
    completed?: boolean;
}
